#!/usr/bin/env bash
# 宇海VPN：上线官网 yhvpn.io + 安卓下载（服务器 root 执行，可重复执行）
set -euo pipefail
IP="${SERVER_IP:?请先设置 SERVER_IP=<CONTROL_PLANE_IP>}"
SITE=/opt/yuhai-vpn/site
APK_SHA=3a681b3461f03676543437f07d4c590fb4424e3165c028d9dd335a73bcbd1080
APK_NAME=yuhai-vpn-1.1.0.apk
SITE_B64=''

echo "==> 1/4 安装官网页面"
rm -rf "$SITE.new"; mkdir -p "$SITE.new/download"
printf '%s' "$SITE_B64" | base64 -d | tar xzf - -C "$SITE.new"
if [ -f "$SITE/download/$APK_NAME" ]; then cp -p "$SITE/download/$APK_NAME" "$SITE.new/download/"; fi
if [ -f /tmp/yuhai-upload.apk ]; then
  got=$(sha256sum /tmp/yuhai-upload.apk | cut -d' ' -f1)
  [ "$got" = "$APK_SHA" ] || { echo "[失败] 安装包校验不一致：$got"; exit 1; }
  mv /tmp/yuhai-upload.apk "$SITE.new/download/$APK_NAME"
fi
[ -f "$SITE.new/download/$APK_NAME" ] || { echo "[失败] 服务器上没有安装包"; exit 1; }
chmod -R a+rX "$SITE.new"
rm -rf "$SITE.old"; [ -d "$SITE" ] && mv "$SITE" "$SITE.old"; mv "$SITE.new" "$SITE"
echo "  安装包 SHA-256 校验通过"

echo "==> 2/4 等待 yhvpn.io 解析生效（最多约 5 分钟）"
for i in $(seq 1 60); do
  a=$(getent ahostsv4 yhvpn.io | awk 'NR==1{print $1}' || true)
  b=$(getent ahostsv4 www.yhvpn.io | awk 'NR==1{print $1}' || true)
  if [ "$a" = "$IP" ] && [ "$b" = "$IP" ]; then echo "  解析已生效"; break; fi
  [ "$i" = 60 ] && { echo "[失败] 解析还没生效（yhvpn.io=$a www=$b），过几分钟再运行一次"; exit 1; }
  sleep 5
done

echo "==> 3/4 写入网站配置"
CF=/etc/caddy/Caddyfile
grep -q "^(secure)" "$CF" || { echo "[失败] 网站总配置缺失，请先运行 setup-domain.sh"; exit 1; }
if ! grep -q '^yhvpn.io {' "$CF"; then
  cp "$CF" "$CF.bak-$(date +%s)"
  cat >> "$CF" <<'CADDY'

www.yhvpn.io {
	redir https://yhvpn.io{uri} permanent
}

yhvpn.io {
	import secure
	encode zstd gzip
	header {
		X-Frame-Options "DENY"
		Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self' https://api.yhvpn.io; frame-ancestors 'none'; base-uri 'none'; form-action 'none'"
	}
	root * /opt/yuhai-vpn/site
	@apk path *.apk
	header @apk Content-Type "application/vnd.android.package-archive"
	header @apk Cache-Control "public, max-age=86400"
	@invite path /i /i/*
	rewrite @invite /i/index.html
	file_server
	handle_errors {
		respond "{err.status_code}" {err.status_code}
	}
}
CADDY
fi
caddy validate --config "$CF" --adapter caddyfile >/dev/null
systemctl reload caddy

echo "==> 4/4 自检（约 30 秒）"
ok=0
for i in $(seq 1 20); do
  c1=$(curl -s -o /dev/null -w '%{http_code}' https://yhvpn.io/ || true)
  c2=$(curl -s -o /dev/null -w '%{http_code}' https://yhvpn.io/download/ || true)
  c3=$(curl -s -o /dev/null -w '%{http_code}' https://www.yhvpn.io/ || true)
  sha=$(curl -s https://yhvpn.io/download/$APK_NAME | sha256sum | cut -d' ' -f1 || true)
  if [ "$c1" = 200 ] && [ "$c2" = 200 ] && [ "$c3" = 301 ] && [ "$sha" = "$APK_SHA" ]; then ok=1; break; fi
  sleep 3
done
printf '  官网首页   https://yhvpn.io/           %s\n' "$c1"
printf '  下载页     https://yhvpn.io/download/  %s\n' "$c2"
printf '  www 跳转   https://www.yhvpn.io/       %s（301=正常）\n' "$c3"
printf '  安装包校验 %s\n' "$( [ "$sha" = "$APK_SHA" ] && echo 一致 || echo 不一致)"
if [ "$ok" = 1 ]; then echo; echo "✅ 官网和安卓下载已上线"; else echo; echo "⚠️ 还没全部通过，把上面内容发给 Claude"; journalctl -u caddy -n 10 --no-pager | tail -n 10; fi
